shellCommands.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { setTimeout as delay } from 'node:timers/promises'

let resolveEvent
const eventReceived = new Promise((resolve) => { resolveEvent = resolve })
const analytics = createServer(async (request, response) => {
  let body = ''
  for await (const chunk of request) body += chunk
  resolveEvent(JSON.parse(body))
  await delay(2000)
  response.writeHead(204).end()
})
await new Promise((resolve) => analytics.listen(0, '127.0.0.1', resolve))
const analyticsPort = analytics.address().port
const app = spawn('npm', ['run', 'start', '--', '-p', '34123'], {
  cwd: '/workspace',
  env: { ...process.env, ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analyticsPort}/events` },
  stdio: ['"'ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', (chunk) => { output += chunk })
app.stderr.on('data', (chunk) => { output += chunk })
try {
  for (let attempt = 0; attempt < 100 && "'!output.includes('"'Ready in'); attempt++) {
    if (app.exitCode "'!== null) throw new Error(`App exited: ${output}`)
    await delay(100)
  }
  if (!output.includes('"'Ready in')) throw new Error("'`App did not start: ${output}`)
  const start = performance.now()
  const response = await fetch('"'http://127.0.0.1:34123/')
  const html = await response.text()
  const elapsed = Math.round(performance.now() - start)
  const event = await Promise.race([eventReceived, delay(5000).then(() => { throw new Error('No analytics event received') })])
  if ("'!response.ok || !html.includes('"'Thanks for visiting"'!'"')) throw new Error('Welcome response missing')
  if (elapsed >= 2000) throw new Error("'`Response was blocked by analytics: ${elapsed} ms`)
  if (event.event !== '"'page_view' || event.path "'!== '"'/') throw new Error("'`Unexpected event: ${JSON.stringify(event)}`)
  process.stdout.write(`Welcome response: ${elapsed} ms; analytics endpoint delay: 2000 ms; event: ${JSON.stringify(event)}'"\\n"'`)
} finally {
  app.kill('"'SIGTERM')
  analytics.close()
}
EOF"
